package tv.plus.pro.unified;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.media.MediaPlayer;
public class VideoPlayerActivity extends Activity{
 VideoView video;int saved=0;@Override public void onCreate(Bundle b){super.onCreate(b);Uri uri=getIntent().getData();if(uri==null){finish();return;}String mime=getIntent().getType();if(mime!=null&&mime.startsWith("image/")){ImageView image=new ImageView(this);image.setBackgroundColor(0xff08091b);image.setScaleType(ImageView.ScaleType.FIT_CENTER);try{image.setImageURI(uri);}catch(Exception e){new AlertDialog.Builder(this).setMessage("Resim açılamadı: "+e.getMessage()).setPositiveButton("Tamam",(d,w)->finish()).show();}setContentView(image);return;}LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff070819);TextView title=new TextView(this);title.setText("▶ TV+  Video Oynatıcı");title.setTextColor(-1);title.setTextSize(22);title.setPadding(18,12,18,12);root.addView(title);video=new VideoView(this);root.addView(video,new LinearLayout.LayoutParams(-1,0,1));MediaController controls=new MediaController(this);controls.setAnchorView(video);video.setMediaController(controls);setContentView(root);video.setOnErrorListener((mp,what,extra)->{new AlertDialog.Builder(this).setMessage("Video oynatılamadı. Bu codec cihazda desteklenmiyor olabilir.").setPositiveButton("Tamam",(d,w)->finish()).show();return true;});video.setVideoURI(uri);video.setOnPreparedListener(mp->{if(saved>0)video.seekTo(saved);video.start();controls.show(3000);});video.requestFocus();}
 @Override protected void onSaveInstanceState(Bundle b){if(video!=null)b.putInt("pos",video.getCurrentPosition());super.onSaveInstanceState(b);}
 @Override protected void onPause(){if(video!=null){saved=video.getCurrentPosition();video.pause();}super.onPause();}
 @Override protected void onResume(){super.onResume();if(video!=null&&saved>0){video.seekTo(saved);video.start();}}
}